[CmdletBinding()]param([ValidateRange(1024,65535)][int]$Port=6620,[switch]$Open,[switch]$Stop)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$server=Join-Path $root 'dashboard\server.mjs';$rt=Join-Path $root 'runtime\lead-dashboard';$record=Join-Path $rt 'server.json'
if(-not(Test-Path $server)){throw "Missing dashboard server: $server"}
if($Stop){if(-not(Test-Path $record)){Write-Output 'Cars Lead Control is not recorded as running.';return};$r=Get-Content $record -Raw|ConvertFrom-Json;$l=@(Get-NetTCPConnection -State Listen -LocalPort ([int]$r.port) -ErrorAction SilentlyContinue);if($l.Count-ne 1-or$l[0].OwningProcess-ne[int]$r.pid){throw 'Dashboard listener ownership changed; refusing to stop.'};Stop-Process -Id ([int]$r.pid) -ErrorAction Stop;Write-Output "Stopped Cars Lead Control PID $($r.pid).";return}
$l=@(Get-NetTCPConnection -State Listen -LocalPort $Port -ErrorAction SilentlyContinue);if($l.Count){throw "Port $Port is occupied by PID $($l[0].OwningProcess)."};New-Item -ItemType Directory -Force -Path $rt|Out-Null;$node=(Get-Command node -ErrorAction Stop).Source;$out=Join-Path $rt 'dashboard.out.log';$err=Join-Path $rt 'dashboard.err.log';$p=Start-Process -FilePath $node -ArgumentList @($server,'--port',[string]$Port) -WorkingDirectory $root -WindowStyle Hidden -PassThru -RedirectStandardOutput $out -RedirectStandardError $err
for($i=0;$i-lt50;$i++){Start-Sleep -Milliseconds 100;$l=@(Get-NetTCPConnection -State Listen -LocalPort $Port -ErrorAction SilentlyContinue);if($l.Count){break};if($p.HasExited){throw "Dashboard exited early. See $err"}}
$l=@(Get-NetTCPConnection -State Listen -LocalPort $Port -ErrorAction SilentlyContinue);if($l.Count-ne1-or$l[0].OwningProcess-ne$p.Id){throw "Dashboard did not claim port $Port. See $err"};$url="http://127.0.0.1:$Port/";Write-Output "Cars Lead Control: $url (PID $($p.Id))";if($Open){Start-Process $url}
